function check(candidate) {
    console.assert(JSON.stringify(candidate([1,2,3,2,1], [3,2,1,4,7])) === JSON.stringify(3));
    console.assert(JSON.stringify(candidate([1,2,3], [3,4,5])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,0,0,0,1], [1,0,0,0,1])) === JSON.stringify(5));
    console.assert(JSON.stringify(candidate([1], [2])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([1], [1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,2,3], [3,2,1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([100,0,100,0,100], [100,0,100,0,100])) === JSON.stringify(5));
    console.assert(JSON.stringify(candidate([1,2,3,2,1], [1,2,3,2,1])) === JSON.stringify(5));
